\begin{equation}
    \left| \frac{1}{N} v^N_{\eps}(0, \mathbf{x}) - \mathcal V_0 \right| \le \underbrace{\frac{L_{\eps}}{2N}}_{\text{Particle Error}} 
    + \underbrace{C_2 \cdot \eps \ln(1/\eps)}_{\text{Regularization Error}},
\end{equation}

\State \textbf{Initialize:} $X_0^{(i)} \leftarrow x_{\text{start}}$ for $i=1,\dots,N$, \State $\Delta t \leftarrow T/(M-1)$
\For{iteration $l = 1$ to $L$}
    \State Sample $Z_1, \dots, Z_S \sim \mathcal{N}(0, I_d)$
    \For{step $m = 0$ to $M-1$}
        \State $t \leftarrow m \Delta t$, $\tau \leftarrow T - t$
